-- Step 1: the cache conversation gains another assistant turn, an empty
-- assistant turn and a tool result. Forge dates usage with the conversation's
-- updated_at, so the fixture deliberately leaves that stamp where it was:
-- moving it would re-date the usage already reported.
UPDATE conversations
   SET context = '{"conversation_id":"conv-a-cache","messages":[{"message":{"text":{"role":"User","content":"Refactor   the cache\nlayer"}}},{"message":{"text":{"role":"Assistant","content":"","model":"claude-sonnet-4-5","tool_calls":[{"name":"shell","call_id":"call-a-1","arguments":{"command":"go test ./internal/cache/..."}},{"name":"Read","call_id":"call-a-2","arguments":{"file_path":"internal/cache/layer.go"}}]}},"usage":{"prompt_tokens":{"actual":1200},"completion_tokens":{"actual":300},"total_tokens":{"actual":1500},"cached_tokens":{"actual":200}}},{"message":{"text":{"role":"Assistant","content":"The probe prints SENTINEL_PRIVATE_TEXT into the trace file.","model":"claude-sonnet-4-5"}}},{"message":{"text":{"role":"Assistant","content":"The layer now sits behind a flag.","model":"claude-sonnet-4-5"}},"usage":{"prompt_tokens":{"actual":900},"completion_tokens":{"actual":180},"total_tokens":{"actual":1080},"cached_tokens":{"actual":100}}},{"message":{"text":{"role":"Assistant","content":"Nothing further to report.","model":"claude-sonnet-4-5"}},"usage":{"prompt_tokens":{"actual":0},"completion_tokens":{"actual":0},"cached_tokens":{"actual":0}}},{"message":{"text":{"role":"Tool","content":"SENTINEL_PRIVATE_TEXT shows up in this tool result as well."}}}]}'
 WHERE conversation_id = 'conv-a-cache';
